fn count_true(arr: &Vec<bool>) -> u64 {
    let mut count: u64 = 0;
    let mut i: usize = 0;

    // Invariant: 0 <= i <= arr.len()
    //            and count == number of true values in arr[0..i]
    while i < arr.len() {
        if arr[i] {
            count += 1;
        }
        i += 1;
    }

    count
}

